  "App Raccourcis → « + » → nommez le raccourci « Envoyer à Pécule ».": "App Atajos → «+» → llama al atajo «Enviar a Pécule».",
  "Réglages du raccourci (ⓘ) : activez « Afficher dans la feuille de partage », types acceptés : Fichiers, PDF, Images.": "Ajustes del atajo (ⓘ): activa «Mostrar en la hoja para compartir», tipos aceptados: Archivos, PDF, Imágenes.",
  "Ajoute l'action « Obtenir le contenu de l'URL » :": "Añade la acción «Obtener contenido de URL»:",
  "(après « name= », insérez la variable « Entrée du raccourci → Nom »).": "(después de «name=», inserta la variable «Entrada del atajo → Nombre»).",
  "Méthode POST ; en-tête « Authorization » = le jeton copié (« Bearer pec_… ») ; corps de la requête : Fichier → « Entrée du raccourci ».": "Método POST; cabecera «Authorization» = el token copiado («Bearer pec_…»); cuerpo de la solicitud: Archivo → «Entrada del atajo».",
  "Ajoute « Afficher la notification » avec le résultat (titre du document rangé).": "Añade «Mostrar notificación» con el resultado (título del documento guardado).",
