  "Système": "Sistema",
  "Aucune modification enregistrée pour l'instant.": "Ningún cambio registrado por ahora.",
  "Fait oublié": "Dato olvidado",
  "Mémoire de l'assistant ({n})": "Memoria del asistente ({n})",
  "Oublier ce fait": "Olvidar este dato",
  "Rien pour l'instant. Dis par exemple à l'assistant « souviens-toi que… » ; il retient aussi de lui-même ce que tu lui expliques (contexte, prélèvements, préférences).": "Nada por ahora. Dile por ejemplo al asistente «recuerda que…»; también retiene por sí mismo lo que le explicas (contexto, domiciliaciones, preferencias).",
  "Ces faits sont propres à chaque membre et joints aux consignes de l'assistant à chaque conversation.": "Estos datos son propios de cada miembro y se añaden a las instrucciones del asistente en cada conversación.",
  "Garde sur cet appareil les dernières données de synthèse (soldes, mois, patrimoine, budget, opérations récentes) 7 jours au plus : l'appli s'ouvre tout de suite, même sans réseau. Effacées à la déconnexion ; jamais les factures, documents ni conversations.": "Guarda en este dispositivo los últimos datos de resumen (saldos, mes, patrimonio, presupuesto, movimientos recientes) durante 7 días como máximo: la app se abre al instante, incluso sin red. Se borran al cerrar sesión; nunca las facturas, los documentos ni las conversaciones.",
  "Données effacées de cet appareil": "Datos borrados de este dispositivo",
  "Actif au prochain lancement de l'appli": "Activo la próxima vez que abras la app",
  "Un nouveau lien remplace l'ancien : les agendas abonnés à l'ancien ne se mettront plus à jour. Continuer ?": "Un enlace nuevo sustituye al anterior: los calendarios suscritos al anterior dejarán de actualizarse. ¿Continuar?",
  "Couper l'abonnement ? Les agendas abonnés ne recevront plus l'échéancier.": "¿Cortar la suscripción? Los calendarios suscritos dejarán de recibir los vencimientos.",
  "Échéancier dans Calendrier": "Vencimientos en Calendario",
  "Abonne Calendrier (iPhone, Mac) à ton échéancier : tâches, mensualités, fins de crédit, garanties, documents qui expirent, calendrier fiscal, avec un rappel la veille. Mis à jour toutes les 6 heures ; le lien est privé, garde-le pour toi.": "Suscribe Calendario (iPhone, Mac) a tus vencimientos: tareas, cuotas mensuales, fin de los préstamos, garantías, documentos que caducan, calendario fiscal, con un recordatorio la víspera. Se actualiza cada 6 horas; el enlace es privado, guárdalo para ti.",
  "Copie ce lien maintenant : il ne sera plus affiché.": "Copia este enlace ahora: no volverá a mostrarse.",
  "S'abonner sur cet appareil": "Suscribirse en este dispositivo",
  "Copier le lien": "Copiar enlace",
  "Abonnement actif depuis le {date}": "Suscripción activa desde el {date}",
  "lu {quand}": "leído {quand}",
  "Nouveau lien": "Nuevo enlace",
  "Couper##abonnement": "Cortar",
  "Créer le lien d'abonnement": "Crear el enlace de suscripción",
  "{quoi} : indisponible en mode démo (rien ne doit toucher à tes vrais appareils ni à tes vrais accès).": "{quoi}: no disponible en modo demo (nada debe tocar tus dispositivos ni tus accesos reales).",
  "Mode démo actif": "Modo demo activo",
  "Données fictives. Touche pour en sortir.": "Datos ficticios. Toca para salir.",
  "Le mode démo est actif.": "El modo demo está activo.",
  "Tout ce que tu vois est fictif : la famille, les comptes, les opérations, les factures, le patrimoine. Tes vraies données restent cachées.": "Todo lo que ves es ficticio: la familia, las cuentas, los movimientos, las facturas, el patrimonio. Tus datos reales siguen ocultos.",
  "Sortie impossible": "No se pudo salir",
  "Vérification…": "Verificando…",
  "Quitter le mode démo": "Salir del modo demo",
  "Face ID, Touch ID ou le code de l'appareil est demandé : personne ne peut sortir de la démo à ta place.": "Se pide Face ID, Touch ID o el código del dispositivo: nadie puede salir de la demo en tu lugar.",
  "Montre Pécule sans rien dévoiler : l'appli passe sur une famille imaginaire, avec ses comptes, ses opérations, ses factures, son patrimoine et son échéancier. Tout fonctionne, l'assistant compris, mais sur ces données fictives.": "Muestra Pécule sin desvelar nada: la app pasa a una familia imaginaria, con sus cuentas, sus movimientos, sus facturas, su patrimonio y sus vencimientos. Todo funciona, incluido el asistente, pero con estos datos ficticios.",
  "Sur cet appareil seulement : les autres membres et tes autres appareils restent sur les vraies données.": "Solo en este dispositivo: los demás miembros y tus otros dispositivos siguen con los datos reales.",
  "Pour revenir à tes données : Face ID ou Touch ID.": "Para volver a tus datos: Face ID o Touch ID.",
  "Synchronisation, notifications et clés d'accès sont coupées pendant la démo ; les données fictives sont remises à neuf chaque jour.": "La sincronización, las notificaciones y las llaves de acceso están desactivadas durante la demo; los datos ficticios se renuevan cada día.",
  "Mode démo indisponible": "Modo demo no disponible",
  "Préparation de la démo…": "Preparando la demo…",
  "Passer en mode démo": "Pasar al modo demo",
  "Mode démo non configuré": "Modo demo no configurado",
  "Réglage indisponible": "Ajuste no disponible",
  "Réglage commun à toute la famille. Le fournisseur choisi reçoit tout ce que Pécule confie à l'IA : questions à l'assistant, factures, documents et bulletins de paie. Les clés sont chiffrées et ne sont plus jamais affichées. Un fournisseur est essayé avant d'être choisi ou modifié : si l'essai échoue, rien ne change.": "Ajuste común a toda la familia. El proveedor elegido recibe todo lo que Pécule confía a la IA: preguntas al asistente, facturas, documentos y nóminas. Las claves están cifradas y no vuelven a mostrarse. Un proveedor se prueba antes de elegirlo o modificarlo: si la prueba falla, nada cambia.",
  "Le mode vocal passe toujours par la ressource Microsoft Foundry.": "El modo de voz pasa siempre por el recurso de Microsoft Foundry.",
  "Le mode vocal a besoin d'une ressource Microsoft Foundry (son nom et sa clé).": "El modo de voz necesita un recurso de Microsoft Foundry (su nombre y su clave).",
  "Utilisé##fournisseur": "En uso",
  "Choisi, incomplet": "Elegido, incompleto",
  "Prêt##fournisseur": "Listo",
  "À configurer": "Por configurar",
