  "Essai impossible": "No se pudo hacer la prueba",
  "Confier l'IA de Pécule à « {nom} » ? Les questions à l'assistant, les factures, les documents et les bulletins de paie lui seront envoyés.": "¿Confiar la IA de Pécule a «{nom}»? Se le enviarán las preguntas al asistente, las facturas, los documentos y las nóminas.",
  "{nom} répond maintenant": "Ahora responde {nom}",
  "Retirer la clé enregistrée ici ? Celle de l'hébergement reprendra la main, s'il y en a une.": "¿Quitar la clave guardada aquí? La del alojamiento volverá a usarse, si hay alguna.",
  "Retirer la clé enregistrée pour ce fournisseur ?": "¿Quitar la clave guardada para este proveedor?",
  "Clé retirée": "Clave quitada",
  "La clé enregistrée n'est plus lisible (le secret du serveur a changé) : ressaisis-la.": "La clave guardada ya no se puede leer (el secreto del servidor ha cambiado): vuelve a introducirla.",
  "Une clé est enregistrée. Laisse vide pour la garder.": "Hay una clave guardada. Deja el campo vacío para conservarla.",
  "Clé posée par l'hébergement. En saisir une ici la remplace.": "Clave definida por el alojamiento. Si introduces una aquí, la sustituye.",
