  "Autorisation refusée : active les notifications de Pécule dans les réglages de l'appareil.": "Permiso denegado: activa las notificaciones de Pécule en los ajustes del dispositivo.",
  "Notifications activées sur cet appareil": "Notificaciones activadas en este dispositivo",
  "Activation impossible": "No se pudo activar",
  "Notifications désactivées sur cet appareil": "Notificaciones desactivadas en este dispositivo",
  "Pour recevoir les notifications sur l'iPhone, installe d'abord Pécule sur l'écran d'accueil (Partager → Sur l'écran d'accueil), puis ouvre l'appli depuis son icône et reviens ici.": "Para recibir las notificaciones en el iPhone, instala primero Pécule en la pantalla de inicio (Compartir → Añadir a pantalla de inicio), luego abre la app desde su icono y vuelve aquí.",
  "Ce navigateur ne gère pas les notifications.": "Este navegador no admite notificaciones.",
  "Reçois sur cet appareil les alertes utiles : opérations à classer, prélèvement nouveau ou inhabituel, solde bas, loyer non reçu, échéances, garanties, enveloppes, et le résumé de la semaine.": "Recibe en este dispositivo los avisos útiles: movimientos por clasificar, domiciliación nueva o inusual, saldo bajo, alquiler no recibido, vencimientos, garantías, sobres y el resumen de la semana.",
  "Activer sur cet appareil": "Activar en este dispositivo",
  "Notification d'essai envoyée": "Notificación de prueba enviada",
  "Aucun appareil n'a reçu l'essai": "Ningún dispositivo ha recibido la prueba",
  "Essai": "Prueba",
  "Désactiver sur cet appareil": "Desactivar en este dispositivo",
  "Dernières notifications": "Últimas notificaciones",
  "Import impossible": "No se pudo importar",
  "Sur BoursoBank : {lien}, tous les comptes, format CSV. Tu peux redéposer le même fichier : rien n'est compté deux fois, et un nom déjà posé n'est jamais remplacé.": "En BoursoBank: {lien}, todas las cuentas, formato CSV. Puedes volver a subir el mismo archivo: nada se cuenta dos veces y un nombre ya puesto nunca se sustituye.",
  "Pour un prélèvement ou un virement, la synchronisation ne transmet souvent qu'une référence. L'export de BoursoBank porte le nom du créancier : dépose-le ici pour nommer ces opérations et les classer comme celles du même nom.": "Para una domiciliación o una transferencia, la sincronización a menudo solo transmite una referencia. La exportación de BoursoBank incluye el nombre del acreedor: súbela aquí para poner nombre a estos movimientos y clasificarlos como los del mismo nombre.",
  "Import en cours…": "Importando…",
  "Déposer l'export CSV": "Subir la exportación CSV",
  "Équivalences amusantes": "Equivalencias divertidas",
  "Pendant un thème, les dépenses se lisent aussi dans l'unité du moment (litres de bière à la Saint-Patrick, kilos de bonbons à Halloween…) et, toute l'année, en temps de travail d'après tes bulletins de paie. Avec, sur l'accueil, « Le chiffre du moment » et ce que coûte la fête en cours. Aucun montant ne change. Valable sur tous tes appareils, assistant compris.": "Durante un tema, los gastos también se leen en la unidad del momento (litros de cerveza en San Patricio, kilos de caramelos en Halloween…) y, todo el año, en tiempo de trabajo según tus nóminas. Además, en el inicio, «La cifra del momento» y lo que cuesta la fiesta en curso. Ningún importe cambia. Válido en todos tus dispositivos, incluido el asistente.",
  "En ce moment ({theme}) : {unite}, soit 100 € ≈ {equivalent}.": "Ahora mismo ({theme}): {unite}, es decir, 100 € ≈ {equivalent}.",
  "En ce moment ({theme}) : {unite}.": "Ahora mismo ({theme}): {unite}.",
  "Équivalences activées": "Equivalencias activadas",
  "Équivalences désactivées": "Equivalencias desactivadas",
  "Logo": "Logo",
  "Le coffre de tous les jours, sur le fond de ton choix. Dans l'appli et dans l'onglet du navigateur, il prend tout seul le décor du thème du moment (en ce moment : {theme}).": "El cofre de todos los días, sobre el fondo que elijas. En la app y en la pestaña del navegador adopta por sí solo la decoración del tema del momento (ahora mismo: {theme}).",
  "Le coffre de tous les jours, sur le fond de ton choix. Dans l'appli et dans l'onglet du navigateur, il prend tout seul le décor du thème du moment.": "El cofre de todos los días, sobre el fondo que elijas. En la app y en la pestaña del navegador adopta por sí solo la decoración del tema del momento.",
  "Icône sur l'écran d'accueil": "Icono en la pantalla de inicio",
  "Comme le logo": "Como el logo",
  "L'iPhone garde l'icône du jour où Pécule a été ajouté à l'écran d'accueil : elle ne peut pas changer toute seule. Pour en changer, ouvre Pécule dans Safari, choisis l'icône ici, supprime l'ancienne de l'écran d'accueil, puis Partager → « Sur l'écran d'accueil ». Il faudra te reconnecter et réactiver les notifications.": "El iPhone conserva el icono del día en que se añadió Pécule a la pantalla de inicio: no puede cambiar solo. Para cambiarlo, abre Pécule en Safari, elige el icono aquí, elimina el antiguo de la pantalla de inicio y luego Compartir → «Añadir a pantalla de inicio». Tendrás que volver a iniciar sesión y reactivar las notificaciones.",
  "Tu es dans l'appli installée : fais ce choix depuis Safari, c'est lui qui crée l'icône.": "Estás en la app instalada: haz esta elección desde Safari, es él quien crea el icono.",
