  "Fixe un plafond mensuel par poste (Alimentation, Restaurants…) : la jauge se remplit au fil du mois, l'alerte tombe à 80 %. Pécule propose la moyenne de tes 3 derniers mois.": "Fija un tope mensual por partida (Alimentación, Restaurantes…): el indicador se va llenando a lo largo del mes y el aviso llega al 80 %. Pécule propone la media de tus 3 últimos meses.",
