  "aucune date fixée": "ninguna fecha fijada",
  "Tes objectifs": "Tus objetivos",
  "Un objectif = un projet (voyage, travaux, voiture, apport…), un montant et une date. Relie-le à un livret ou un placement : l'avancement suit sa valeur, et Pécule calcule le versement mensuel pour tenir la date.": "Un objetivo = un proyecto (viaje, obras, coche, entrada…), un importe y una fecha. Vincúlalo a una cuenta de ahorro o a una inversión: el progreso sigue su valor y Pécule calcula la aportación mensual para cumplir la fecha.",
