  "Retirer cet accord ? Les opérations déjà lues restent dans Pécule.": "¿Retirar este consentimiento? Los movimientos ya leídos se quedan en Pécule.",
  "Accord retiré": "Consentimiento retirado",
  "Retirer": "Retirar",
  "Encours des cartes à débit différé": "Importe pendiente de las tarjetas de débito diferido",
