  "Relier": "Vincular",
  "Tu passeras par une page d'accord puis par ta banque. Valide sans attendre : la page d'accord expire au bout d'un quart d'heure. La banque doit d'abord avoir été reliée dans la console d'Enable Banking.": "Pasarás por una página de consentimiento y luego por tu banco. Valida sin esperar: la página de consentimiento caduca al cabo de un cuarto de hora. El banco debe haberse vinculado antes en la consola de Enable Banking.",
  "Lecture terminée": "Lectura terminada",
  "Lire maintenant": "Leer ahora",
  "Oublier la clé et tous les accords ? Les opérations déjà lues restent dans Pécule.": "¿Olvidar la clave y todos los consentimientos? Los movimientos ya leídos se quedan en Pécule.",
  "Clé oubliée": "Clave olvidada",
  "Période d'observation : les comptes lus par Enable Banking sont gardés à part, masqués et hors statistiques, le temps de les comparer à ta source actuelle. Rien n'est compté deux fois.": "Periodo de observación: las cuentas leídas por Enable Banking se guardan aparte, ocultas y fuera de las estadísticas, mientras se comparan con tu fuente actual. Nada se cuenta dos veces.",
