  "« Datées autrement » : des achats de fin de mois que la banque prélève un mois plus tard que ce que Pécule supposait. La date de la banque fera foi.": "«Fechados de otro modo»: compras de fin de mes que el banco carga un mes más tarde de lo que Pécule suponía. Prevalecerá la fecha del banco.",
  "Comparer avec mes comptes actuels": "Comparar con mis cuentas actuales",
