  "Ta clé personnelle": "Tu clave personal",
  "Oublier ma clé": "Olvidar mi clave",
  "Oublier ta clé personnelle et tes accords ? Les opérations déjà lues restent dans Pécule.": "¿Olvidar tu clave personal y tus consentimientos? Los movimientos ya leídos se quedan en Pécule.",
  "J'ai des comptes à mon seul nom": "Tengo cuentas solo a mi nombre",
  "L'usage gratuit d'Enable Banking ne couvre que les comptes de la personne inscrite. Si tu as des comptes à ton seul nom, crée ta propre application sur enablebanking.com et donne ici sa clé : elle servira à tes accords.": "El uso gratuito de Enable Banking solo cubre las cuentas de la persona registrada. Si tienes cuentas solo a tu nombre, crea tu propia aplicación en enablebanking.com e indica aquí su clave: servirá para tus consentimientos.",
  "Synchronisations bancaires": "Sincronizaciones bancarias",
  "alertes techniques journal audit synchronisation banque": "alertas técnicas registro auditoría sincronización banco",
  "Synchroniser les comptes bancaires": "Sincronizar las cuentas bancarias",
  "Compte importé": "Cuenta importada",
  "Dépose l'export de ta banque (OFX, QIF ou CSV) : ses opérations rejoignent le compte choisi. Tu peux redéposer un fichier qui recouvre le précédent, rien n'est ajouté deux fois.": "Deja aquí la exportación de tu banco (OFX, QIF o CSV): sus movimientos se añaden a la cuenta elegida. Puedes dejar un archivo que se solape con el anterior; nada se añade dos veces.",
