  "Par l'interface officielle de ta banque, en lecture seule (Enable Banking, gratuit pour un usage personnel).": "Por la interfaz oficial de tu banco, solo lectura (Enable Banking, gratis para uso personal).",
  "Importer un fichier de ta banque": "Importar un archivo de tu banco",
  "L'export OFX, QIF ou CSV de ton espace client : aucun service à relier.": "La exportación OFX, QIF o CSV de tu área de cliente: ningún servicio que conectar.",
  "Brancher l'assistant": "Conectar el asistente",
  "Facultatif : avec ta propre clé d'IA, Pécule lit tes factures et répond à tes questions.": "Opcional: con tu propia clave de IA, Pécule lee tus facturas y responde a tus preguntas.",
  "Bien démarrer": "Primeros pasos",
  "Pécule est installé et ton foyer est créé. Donne-lui ses premières opérations : tout le reste en découle.": "Pécule está instalado y tu hogar está creado. Dale sus primeros movimientos: todo lo demás sale de ahí.",
  "Voir Pécule rempli, avec une famille fictive": "Ver Pécule lleno, con una familia ficticia",
  "Écrans affichés": "Pantallas mostradas",
  "Un écran retiré sort du menu, de la recherche et des raccourcis pour tout le foyer. Ses données restent en place : le remettre les retrouve telles quelles.": "Una pantalla retirada sale del menú, de la búsqueda y de los atajos para todo el hogar. Sus datos siguen en su sitio: al volver a ponerla los recuperas tal cual.",
  "Seul l'administrateur du foyer peut changer ces réglages.": "Solo el administrador del hogar puede cambiar estos ajustes.",
  "Personnes et banques": "Personas y bancos",
  "Personnes sans connexion": "Personas sin acceso",
  "Un enfant, par exemple : ses comptes portent son prénom et lui sont attribués. Sépare les prénoms par une virgule.": "Un hijo, por ejemplo: las cuentas que llevan su nombre se le atribuyen. Separa los nombres con una coma.",
  "Banques des comptes professionnels": "Bancos de las cuentas profesionales",
  "Nom de la banque": "Nombre del banco",
  "Les comptes de ces banques sont rangés à part, masqués et hors statistiques dès leur arrivée.": "Las cuentas de estos bancos se guardan aparte, ocultas y fuera de las estadísticas desde que llegan.",
  "Foyer enregistré": "Hogar guardado",
  "Biens, valeur, loyers, taxe foncière": "Inmuebles, valor, alquileres, impuesto sobre bienes inmuebles",
  "Positions, cours, journal des mouvements": "Posiciones, cotizaciones, registro de movimientos",
