  "L'assistant n'est pas branché": "El asistente no está conectado",
  "Pécule fonctionne sans IA : seules la lecture automatique des factures et des documents et les réponses à tes questions en dépendent. Pour les activer, ajoute la clé de ton fournisseur d'IA.": "Pécule funciona sin IA: solo dependen de ella la lectura automática de facturas y documentos y las respuestas a tus preguntas. Para activarlas, añade la clave de tu proveedor de IA.",
