  "Choisir des fichiers": "Elegir archivos",
  "Chaque fichier est rangé au coffre. Ceux que Pécule sait lire donnent une proposition, que tu relis avant qu'elle ne soit écrite dans tes écrans ; tout import peut être annulé. La lecture passe par ton fournisseur d'IA : le coût est estimé avant, mesuré ensuite, et plafonné par lot.": "Cada archivo se archiva en la caja fuerte. Los que Pécule sabe leer dan una propuesta, que revisas antes de que se escriba en tus pantallas; cualquier importación se puede deshacer. La lectura pasa por tu proveedor de IA: el coste se estima antes, se mide después y tiene un tope por lote.",
