  "Finta se branche par la variable FINTA_API_KEY de l'hébergement. Un compte que tu as rattaché à Enable Banking n'est plus alimenté par Finta.": "Finta se conecta mediante la variable FINTA_API_KEY del alojamiento. Una cuenta que has vinculado a Enable Banking deja de recibir datos de Finta.",
