  "Ce que tu possèdes (comptes, épargne, biens, crypto) moins ce que tu dois encore. Les biens et les crédits communs comptent pour ta part.": "Lo que tienes (cuentas, ahorros, bienes, cripto) menos lo que aún debes. Los bienes y los préstamos comunes cuentan por tu parte.",
  "Ce qu'il y a sur tes comptes aujourd'hui. Les achats par carte à débit différé pas encore prélevés n'en sont pas déduits.": "Lo que hay hoy en tus cuentas. Las compras con tarjeta de débito diferido aún no cargadas no se descuentan.",
  "Revenus du mois moins dépenses du mois. Les mouvements entre tes comptes et les versements d'épargne ne comptent pas.": "Ingresos del mes menos gastos del mes. Los movimientos entre tus cuentas y los aportes de ahorro no cuentan.",
