  "Surveiller mes soldes": "Vigilar mis saldos",
  "Pécule te prévient quand un compte est sous son seuil, ou va y passer.": "Pécule te avisa cuando una cuenta está por debajo de su umbral, o va a estarlo.",
  "Seuil": "Umbral",
  "En dessous de ce montant, un compte est signalé. Un montant négatif prévient avant la limite d'un découvert autorisé.": "Por debajo de este importe, se señala la cuenta. Un importe negativo avisa antes del límite de un descubierto autorizado.",
  "Me prévenir": "Avisarme",
  "Combien de jours avant que le compte passe sous le seuil (j = jours).": "Cuántos días antes de que la cuenta baje del umbral (j = días).",
  "{n} j": "{n} j",
  "Comptes surveillés — décoche un compte pour l'écarter, ou donne-lui un seuil à lui (vide : le seuil ci-dessus).": "Cuentas vigiladas — desmarca una cuenta para excluirla, o dale un umbral propio (vacío: el umbral de arriba).",
  "Comment c'est calculé : le solde du jour, puis ce qui est attendu sur ce compte d'ici là, en entrées comme en sorties — ce qui y revient chaque mois (prélèvements, virements, salaire) et le relevé d'une carte à débit différé. Les achats du quotidien ne sont pas devinés : c'est une estimation, à lire comme « au mieux ». L'alerte arrive en notification si « Solde bas » est activé sur l'appareil, et se lit aussi sur le calendrier du mois et le tableau de bord. Tu peux demander à l'assistant de changer ces réglages.": "Cómo se calcula: el saldo de hoy, y luego lo que se espera en esta cuenta hasta entonces, entradas y salidas — lo que vuelve cada mes (domiciliaciones, transferencias, nómina) y el extracto de una tarjeta de débito diferido. Las compras del día a día no se adivinan: es una estimación, que se lee como «en el mejor de los casos». El aviso llega como notificación si «Saldo bajo» está activado en el dispositivo, y también se ve en el calendario del mes y en el panel. Puedes pedirle al asistente que cambie estos ajustes.",
  "{compte} est sous son seuil : {montant}.": "{compte} está por debajo de su umbral: {montant}.",
  "{compte} passerait à {montant} le {date}, après {cause}.": "{compte} bajaría a {montant} el {date}, tras {cause}.",
  "{compte} passerait à {montant} le {date}.": "{compte} bajaría a {montant} el {date}.",
  "Régler l'alerte de solde bas": "Ajustar el aviso de saldo bajo",
  "Solde bas": "Saldo bajo",
  "Solde bas, alertes de cet appareil, ouverture instantanée": "Saldo bajo, avisos de este dispositivo, apertura instantánea",
