  "ne pas l'afficher": "no mostrarlo",
  "Soldes prévus ce jour-là": "Saldos previstos ese día",
  "Régler l'alerte": "Ajustar el aviso",
  "Aucun compte à suivre pour l'instant.": "Ninguna cuenta que seguir por ahora.",
  "La surveillance des soldes est coupée : aucun compte n'est signalé.": "La vigilancia de saldos está apagada: no se señala ninguna cuenta.",
  "Aucun compte surveillé ne passe sous son seuil dans les {jours} jours.": "Ninguna cuenta vigilada baja de su umbral en los próximos {jours} días.",
  "Comment c'est calculé : le solde du jour, puis ce qui est attendu sur ce compte, en entrées comme en sorties — ce qui y revient chaque mois (prélèvements, virements, salaire) et le relevé d'une carte à débit différé. Un prélèvement dont le jour habituel est passé depuis peu est compté dès aujourd'hui. Les achats du quotidien ne sont pas devinés : c'est une estimation, à lire comme « au mieux ».": "Cómo se calcula: el saldo de hoy, y luego lo que se espera en esta cuenta, entradas y salidas — lo que vuelve cada mes (domiciliaciones, transferencias, nómina) y el extracto de una tarjeta de débito diferido. Una domiciliación cuyo día habitual pasó hace poco cuenta desde hoy. Las compras del día a día no se adivinan: es una estimación, que se lee como «en el mejor de los casos».",
  "sous le seuil": "por debajo del umbral",
  "{montant} le {date}": "{montant} el {date}",
  "au-dessus du seuil": "por encima del umbral",
  "Pour rester au-dessus du seuil, il manquerait {montant} au plus bas, le {date}.": "Para seguir por encima del umbral, faltarían {montant} en el punto más bajo, el {date}.",
  "En pointillé : le seuil. Le point : le plus bas des jours à venir.": "Discontinua: el umbral. El punto: el mínimo de los próximos días.",
  "Mouvements attendus": "Movimientos previstos",
  "Solde après": "Saldo después",
  "en retard, attendu d'un jour à l'autre": "con retraso, se espera de un día para otro",
  "Rien d'attendu sur ce compte d'ici là.": "Nada previsto en esta cuenta hasta entonces.",
  "Mois (AAAA-MM)": "Mes (AAAA-MM)",
  "Voir le compte signalé": ["Ver la cuenta señalada", "Ver las {n} cuentas señaladas"],
  "Ce qui est attendu sur tes comptes, {n} jour à l'avance": ["Lo que se espera en tus cuentas, con {n} día de antelación", "Lo que se espera en tus cuentas, con {n} días de antelación"],
  "{n} compte est sous son seuil, ou y passerait dans les {jours} jours.": ["{n} cuenta está por debajo de su umbral, o lo estaría en {jours} días.", "{n} cuentas están por debajo de su umbral, o lo estarían en {jours} días."],
  "Afficher les montants (M)": "Mostrar los importes (M)",
  "Masquer les montants (M)": "Ocultar los importes (M)",
  "Afficher les montants": "Mostrar los importes",
  "Masquer les montants": "Ocultar los importes",
  "Masqués": "Ocultos",
  "Visibles": "Visibles",
  "Masquer ou afficher les montants": "Ocultar o mostrar los importes",
  "Ce qui est classé en revenu sur la période ; une entrée sans catégorie compte aussi. Les mouvements entre tes comptes n'en font pas partie.": "Lo que está clasificado como ingreso en el periodo; una entrada sin categoría también cuenta. Los movimientos entre tus cuentas no entran.",
  "Ce qui est classé en dépense, remboursements déduits ; une sortie sans catégorie compte aussi. Ni l'épargne ni les mouvements entre tes comptes.": "Lo que está clasificado como gasto, reembolsos descontados; una salida sin categoría también cuenta. Ni el ahorro ni los movimientos entre tus cuentas.",
  "Ce qui est classé en épargne : les versements vers un livret, une assurance-vie, un plan d'épargne.": "Lo que está clasificado como ahorro: los aportes a una libreta, un seguro de vida, un plan de ahorro.",
  "Revenus moins dépenses. L'épargne n'en est pas retirée : c'est ce qui reste avant de mettre de côté.": "Ingresos menos gastos. El ahorro no se resta: es lo que queda antes de apartar dinero.",
  "Somme des revenus mensuels nets que tu as renseignés (salaires, loyers…).": "Suma de los ingresos mensuales netos que has indicado (nóminas, alquileres…).",
  "Somme, ramenée au mois, de tes engagements en cours : la liste plus bas.": "Suma, llevada al mes, de tus compromisos en curso: la lista de más abajo.",
  "Revenus du foyer moins charges fixes : ce qu'il reste chaque mois pour tout le reste.": "Ingresos del hogar menos gastos fijos: lo que queda cada mes para todo lo demás.",
  "Revenus du foyer moins ce que tu dépenses vraiment par mois, en moyenne sur les trois derniers mois complets.": "Ingresos del hogar menos lo que gastas de verdad al mes, de media en los tres últimos meses completos.",
  "Achats déjà faits avec une carte à débit différé : la banque les prélèvera en une fois, à la date indiquée.": "Compras ya hechas con una tarjeta de débito diferido: el banco las cargará de una vez, en la fecha indicada.",
  "Dépenses du mois en cours, remboursements déduits. L'étiquette compare au mois dernier, à la même date.": "Gastos del mes en curso, reembolsos descontados. La etiqueta compara con el mes pasado, en la misma fecha.",
  "Capital qu'il te reste à rembourser sur tes crédits, pour ta part.": "Capital que te queda por devolver de tus préstamos, por tu parte.",
  "Valeur estimée moins capital restant dû sur les crédits du bien.": "Valor estimado menos el capital pendiente de los préstamos del bien.",
  "Loyers d'une année rapportés au coût d'acquisition (prix et frais).": "Alquileres de un año en relación con el coste de adquisición (precio y gastos).",
  "Densité": "Densidad",
  "Aérée": "Amplia",
  "Compacte": "Compacta",
  "« Compacte » resserre les marges et les lignes pour montrer plus d'opérations par écran, sans réduire le texte. Sur ordinateur seulement ; choix mémorisé sur cet appareil.": "«Compacta» reduce márgenes y filas para mostrar más operaciones por pantalla, sin encoger el texto. Solo en ordenador; la elección se guarda en este dispositivo.",
  "Tout ce que tu possèdes, avant de retirer ce que tu dois encore.": "Todo lo que tienes, antes de restar lo que aún debes.",
  "Comptes courants et épargne : ce qui se mobilise sans vendre un bien ni un placement.": "Cuentas corrientes y ahorro: lo que se puede usar sin vender un bien ni una inversión.",
  "Compare mon engagement n° {id} « {nom} » à l'offre que je te joins et dis-moi laquelle est la plus avantageuse.": "Compara mi compromiso n.º {id} «{nom}» con la oferta que te adjunto y dime cuál es la más ventajosa.",
  "Joins le devis à ta demande (trombone) avant de l'envoyer.": "Adjunta el presupuesto a tu solicitud (clip) antes de enviarla.",
