  "Change ce réglage de Pécule : ": "Cambia este ajuste de Pécule: ",
  "Pose une question sur tes dépenses, tes comptes, ton patrimoine ou tes crédits, ou sur Pécule lui-même, joins une facture ou un document (trombone) pour le ranger, ou demande une action. Chaque action t'est soumise avant d'être faite.": "Haz una pregunta sobre tus gastos, cuentas, patrimonio o préstamos, o sobre el propio Pécule, adjunta una factura o un documento (clip) para archivarlo, o pide una acción. Cada acción se te muestra antes de realizarse.",
  "Tu pourras retirer cet accès à tout moment dans Réglages → Comptes et connexions.": "Podrás retirar este acceso en cualquier momento en Ajustes → Cuentas y conexiones.",
  "Chercher dans le manuel…": "Buscar en el manual…",
  "Il connaît ce manuel, t'y renvoie, et peut faire certains réglages à ta place.": "Conoce este manual, te remite a él y puede cambiar algunos ajustes por ti.",
