  "Une seconde rangée de pastilles filtre par nature de contrat : assurance auto, assurance habitation, assurance emprunteur, mutuelle santé, électricité et gaz, box internet, forfait mobile. Elle réunit tous les papiers d'un même contrat (contrat, avenant, attestation, devis concurrent), quel que soit leur domaine. Seules les natures présentes dans ton coffre sont proposées.": "Una segunda fila de etiquetas filtra por tipo de contrato: seguro de coche, seguro de hogar, seguro de préstamo, seguro de salud, electricidad y gas, internet de casa, tarifa móvil. Reúne todos los papeles de un mismo contrato (contrato, suplemento, certificado, presupuesto de la competencia), sea cual sea su ámbito. Solo se proponen los tipos presentes en tu caja fuerte.",
  "[[Nature du contrat]], dans [[Modifier]], range le document sous une pastille ou l'en retire. Pécule la reconnaît à la lecture ; corrige-la s'il s'est trompé.": "[[Nature du contrat]], en [[Modifier]], coloca el documento bajo una etiqueta o lo quita de ella. Pécule la reconoce al leerlo; corrígela si se ha equivocado.",
  "chercher document retrouver modifier renommer supprimer privé télécharger ouvrir fichier étiquette pastille filtre assurance auto habitation emprunteur mutuelle électricité gaz": "buscar documento encontrar editar modificar renombrar eliminar borrar privado descargar abrir archivo etiqueta filtro seguro coche hogar préstamo salud electricidad gas",
