  "Épargne non classée": "Ahorro sin clasificar",
  "[[Répartition]] : le solde de la période, puis trois anneaux — revenus, dépenses, épargne — et la liste de celui que tu choisis, avec une barre par poste. [[Comparer à]] choisit la référence : le mois précédent, la moyenne des trois derniers mois ou le même mois de l'an dernier. Un trait sur une barre marque le plafond de son enveloppe.": "[[Répartition]]: el saldo del periodo, luego tres anillos — ingresos, gastos, ahorro — y la lista del que elijas, con una barra por partida. [[Comparer à]] elige la referencia: el mes anterior, la media de los tres últimos meses o el mismo mes del año pasado. Una marca en una barra señala el tope de su sobre.",
